//! C: `azul.h` (`target/codegen/azul.h`, generated by `doc/src/codegen/v2/lang_c.rs`).
//!
//! Spellings: `Az<Class>_<lowerCamelMethod>(..)` for api.json constructors
//! (`AzCssProperty_textColor`, `AzFloatValue_create`); C-like enums are plain
//! constants `Az<Enum>_<Variant>` (`AzLayoutDisplay_Flex`); tagged unions use
//! the generated variant constructors `Az<Enum>_<lowerCamelVariant>(payload)`
//! (`AzLayoutWidth_px(..)`, unit: `AzLayoutWidth_auto()`); a monomorphized
//! `CssPropertyValue<T>` alias (and a `CssProperty` variant whose constructor
//! name is taken by a hand-written api.json function) has no constructor and
//! is a compound literal `(AzLayoutWidthValue){ .Exact = { .tag =
//! AzLayoutWidthValue_Tag_Exact, .payload = .. } }`; structs are compound
//! literals with designated initializers; a Vec is
//! `AzXxxVec_copyFromPtr((AzXxx[]){ .. }, n)` (empty: `AzXxxVec_create()`);
//! strings are `AzString_copyFromBytes((const uint8_t*)"..", 0, len)`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Ident, Item, Module, Prim},
    lang::{
        block_comment_safe, c_escape,
        dom::{c_family_registration, unused_params, uses_concat, uses_params, C_CONCAT_HELPER},
        expr_doc_top, item_comments, uses_nonfinite_float, variant_ctor_method, ConcatPart,
        ExprSyntax, MethodLayout,
    },
    CodegenBackend, GeneratedFile,
};

/// C keywords (and `main`) a parameter name must not be: they get a `_`.
const KEYWORDS: &[&str] = &[
    "auto", "break", "case", "char", "const", "continue", "default", "do", "double", "else",
    "enum", "extern", "float", "for", "goto", "if", "inline", "int", "long", "register",
    "restrict", "return", "short", "signed", "sizeof", "static", "struct", "switch", "typedef",
    "union", "unsigned", "void", "volatile", "while", "bool", "true", "false", "main", "NULL",
];

/// A parameter's C name (`const char*`).
pub(crate) fn c_param(name: &Ident) -> String {
    let s = name.snake();
    if KEYWORDS.contains(&s.as_str()) {
        format!("{s}_")
    } else {
        s
    }
}

/// The C printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct C;

/// `(AzLayoutWidthValue){ .Exact = { .tag = AzLayoutWidthValue_Tag_Exact, .payload = x } }`
pub(crate) fn c_union_literal(ty: &str, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
    let mut inner = vec![Doc::text(format!(".tag = Az{ty}_Tag_{variant}"))];
    if let Some(payload) = args.into_iter().next() {
        inner.push(Doc::cat(vec![Doc::text(".payload = "), payload]));
    }
    Doc::cat(vec![
        Doc::text(format!("(Az{ty})")),
        Doc::list(
            "{",
            vec![Doc::cat(vec![
                Doc::text(format!(".{variant} = ")),
                Doc::list("{", inner, ", ", "}", true, broken, false),
            ])],
            ", ",
            "}",
            true,
            broken,
            false,
        ),
    ])
}

impl ExprSyntax for C {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let suffix = if ty == Prim::F64 { "" } else { "f" };
        match text {
            "nan" => "NAN".to_string(),
            "inf" => "INFINITY".to_string(),
            "-inf" => "-INFINITY".to_string(),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "AzString_copyFromBytes((const uint8_t*)\"{}\", 0, {})",
            c_escape(s),
            s.len()
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            EnumShape::Tagged => Doc::call(format!("Az{ty}_{}", variant_ctor_method(variant)), args, broken),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                c_union_literal(ty, variant, args, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!(".{k} = ")), v]))
            .collect();
        Doc::cat(vec![
            Doc::text(format!("(Az{ty})")),
            Doc::list("{", fields, ", ", "}", true, broken, true),
        ])
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("Az{ty}_create()"));
        }
        let n = items.len();
        Doc::cat(vec![
            Doc::text(format!("Az{ty}_copyFromPtr")),
            Doc::list(
                "(",
                vec![
                    Doc::cat(vec![
                        Doc::text(format!("(Az{elem}[])")),
                        Doc::list("{", items, ", ", "}", true, broken, true),
                    ]),
                    Doc::text(n.to_string()),
                ],
                ", ",
                ")",
                false,
                broken,
                false,
            ),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("/* unsupported: {} */ {{0}}", block_comment_safe(what)))
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `AzDom_withChild(recv, child)`: the C API takes `self` as the first
    /// argument; a chain nests.
    fn method(&self, recv: Doc, class: &str, method: &str, args: Vec<Doc>, layout: MethodLayout) -> Doc {
        let mut all = vec![recv];
        all.extend(args);
        Doc::call(format!("Az{class}_{}", snake_to_lower_camel(method)), all, layout.node_tall)
    }

    /// A `const char*` parameter, copied into a fresh `AzString` at every
    /// use (a call takes its `AzString` by value).
    fn param(&self, name: &Ident) -> Doc {
        let p = c_param(name);
        Doc::text(format!("AzString_copyFromBytes((const uint8_t*){p}, 0, strlen({p}))"))
    }

    fn concat(&self, parts: &[ConcatPart<'_>]) -> Doc {
        let mut args: Vec<String> = parts
            .iter()
            .map(|p| match p {
                ConcatPart::Lit(s) => format!("\"{}\"", c_escape(s)),
                ConcatPart::Param(i) => c_param(i),
            })
            .collect();
        args.push("(const char*)NULL".to_string());
        Doc::text(format!("az_concat({})", args.join(", ")))
    }

    fn item_call_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `render_card("Hi", title)`: another function of the header (defined
    /// above it: the module lists callees first).
    fn item_call(&self, item: &Ident, _params: &[Ident], args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(item.snake(), args, broken)
    }

    /// A `const char*` argument: a literal or a parameter passed on.
    fn native_string(&self, parts: &[ConcatPart<'_>]) -> Doc {
        match parts {
            [] => Doc::text("\"\""),
            [ConcatPart::Lit(s)] => Doc::text(format!("\"{}\"", c_escape(s))),
            [ConcatPart::Param(p)] => Doc::text(c_param(p)),
            _ => self.unsupported(C_JOINED_ARG),
        }
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::ItemCall { args, .. } if args.iter().any(|a| matches!(a, Expr::Concat(_))) => {
                Some(C_JOINED_ARG.to_string())
            }
            _ => None,
        }
    }
}

/// Why C cannot pass a text joined from parameters to a component's render
/// function.
const C_JOINED_ARG: &str = "a component's text is a `const char*`: a text joined from parameters \
                            would need a buffer the caller frees";

/// `const char* a, const char* b` (or `void`), and the `(void)x;` lines of
/// the parameters the body never reads.
pub(crate) fn c_params(item: &Item, ty: &dyn Fn(&str) -> String) -> (String, String) {
    let sig = if item.params.is_empty() {
        "void".to_string()
    } else {
        item.params
            .iter()
            .map(|p| format!("{} {}", ty(&p.ty), c_param(&p.name)))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let unused: String = unused_params(item)
        .iter()
        .map(|p| format!("    (void){};\n", c_param(&p.name)))
        .collect();
    (sig, unused)
}

fn c_param_type(ty: &str) -> String {
    if ty == "String" {
        "const char*".to_string()
    } else {
        format!("Az{ty}")
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&C, item) {
        out.push_str(&format!("/* {} */\n", block_comment_safe(line)));
    }
    let body = render(&expr_doc_top(&C, &item.value), "    ", 1);
    let (sig, unused) = c_params(item, &c_param_type);
    out.push_str(&format!(
        "static Az{} {}({sig}) {{\n{unused}    return {body};\n}}\n",
        item.ty,
        item.name.snake()
    ));
    out
}

/// A string literal as an `AzString` (for the app's window title).
fn c_az_str(s: &str) -> String {
    C.string(s).flat()
}

/// The app around a DOM module (`m.app`): a reflected app data type, a
/// layout callback returning the root item, and `main`.
fn c_app_main(m: &Module, module_file: &str) -> String {
    let Some(app) = &m.app else {
        return String::new();
    };
    let root = app.root.snake();
    let body = if app.is_body {
        format!("{root}()")
    } else {
        format!("AzDom_withChild(AzDom_createBody(), {root}())")
    };
    format!(
        "/* {title} - generated by AzBuilder (azul-css codegen, C). */\n#include \
         \"{module_file}\"\n\ntypedef struct {{ int unused; }} AppData;\nstatic void \
         AppData_destructor(void* p) {{ (void)p; }}\nAZ_REFLECT(AppData, \
         AppData_destructor);\n\nstatic AzDom layout(AzRefAny data, AzLayoutCallbackInfo info) \
         {{\n    (void)data;\n    (void)info;\n    return {body};\n}}\n\nint main(void) {{\n    \
         AppData model = {{ 0 }};\n    AzRefAny data = AppData_upcast(model);\n    \
         AzWindowCreateOptions window = AzWindowCreateOptions_create(layout);\n    \
         window.window_state.title = {title_str};\n    AzApp app = AzApp_create(data, \
         AzAppConfig_create());\n    AzApp_run(&app, window);\n    AzApp_delete(&app);\n    \
         return 0;\n}}\n",
        title = block_comment_safe(&app.title),
        title_str = c_az_str(&app.title),
    )
}

impl CodegenBackend for C {
    fn lang(&self) -> &'static str {
        "c"
    }

    fn display_name(&self) -> &'static str {
        "C"
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn extension(&self) -> &'static str {
        "h"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "/* Generated by azul-css codegen (C). Do not edit by hand. */\n#include \"azul.h\"\n",
        );
        if uses_nonfinite_float(m) {
            out.push_str("#include <math.h>\n");
        }
        let concat = uses_concat(m);
        let registration = m.library.is_some();
        if concat || registration {
            out.push_str("#include <stdarg.h>\n#include <stdlib.h>\n");
        }
        if concat || registration || uses_params(m) {
            out.push_str("#include <string.h>\n");
        }
        if concat {
            out.push_str(C_CONCAT_HELPER);
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        if let Some(lib) = &m.library {
            out.push_str(&c_family_registration(m, lib, &c_param, &c_az_str));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        if m.app.is_some() {
            return vec![
                GeneratedFile {
                    path: "ui.h".to_string(),
                    contents: self.emit_module(m),
                },
                GeneratedFile {
                    path: "main.c".to_string(),
                    contents: c_app_main(m, "ui.h"),
                },
                GeneratedFile {
                    path: "Makefile".to_string(),
                    contents: "# AZUL_INCLUDE: the directory holding azul.h; AZUL_LIB: the one \
                               holding libazul\nAZUL_INCLUDE ?= .\nAZUL_LIB ?= .\n\napp: main.c \
                               ui.h\n\t$(CC) -o app main.c -I$(AZUL_INCLUDE) -L$(AZUL_LIB) -lazul\n"
                        .to_string(),
                },
            ];
        }
        let mut main = String::from("#include <stdio.h>\n#include \"styles.h\"\n\nint main(void) {\n");
        for item in &m.items {
            // the local must not shadow the function it is initialised from
            let name = item.name.snake();
            main.push_str(&format!("    Az{} {name}_value = {name}();\n", item.ty));
            if item.ty.ends_with("Vec") {
                main.push_str(&format!(
                    "    printf(\"{name}: %zu properties\\n\", {name}_value.len);\n"
                ));
            } else {
                main.push_str(&format!("    printf(\"{name}: built\\n\");\n"));
            }
            main.push_str(&format!("    Az{}_delete(&{name}_value);\n", item.ty));
        }
        main.push_str("    return 0;\n}\n");
        vec![
            GeneratedFile {
                path: "styles.h".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.c".to_string(),
                contents: main,
            },
            GeneratedFile {
                path: "Makefile".to_string(),
                contents: "# AZUL_INCLUDE: the directory holding azul.h; AZUL_LIB: the one holding \
                           libazul\nAZUL_INCLUDE ?= .\nAZUL_LIB ?= .\n\napp: main.c styles.h\n\t$(CC) \
                           -o app main.c -I$(AZUL_INCLUDE) -L$(AZUL_LIB) -lazul\n"
                    .to_string(),
            },
        ]
    }
}
